211	    /**
212	     * The owner's numeric membership level, derived on read: it starts at 1, gains 1 when an email
213	     * is present, gains 1 when {@link #namesakeCount} is 0, and is capped at 3 by these pre-tenure
214	     * factors. Level 4 is reserved for tenure: it is reached only when the pre-tenure factors are
215	     * maxed and the owner's tenure (whole days from {@link #registrationDate} to today) exceeds 365.
216	     * Because a newly created owner has zero tenure, a new owner never exceeds level 3.
217	     */
218	    @Transient
219	    public Integer getMembershipLevel() {
220	        int level = 1;
221	        if (this.email != null && !this.email.isBlank()) {
222	            level++;
223	        }
224	        if (this.namesakeCount != null && this.namesakeCount == 0) {
225	            level++;
226	        }
227	        level = Math.min(level, 3);
228	        if (this.registrationDate != null
229	                && java.time.temporal.ChronoUnit.DAYS.between(this.registrationDate, LocalDate.now()) > 365) {
230	            level++;
