274	    /** Region -> inclusive 4-digit postcode range {low, high}, used to derive the region from the
275	     *  postcode ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}). */
276	    private static final Map<String, int[]> REGION_POSTCODE_RANGES = Map.of(
277	        "NSW", new int[] {2000, 2099},
278	        "VIC", new int[] {3000, 3099},
279	        "QLD", new int[] {4000, 4099});
280	
281	    /**
282	     * The owner's region, derived on read. The postcode is preferred: a 4-digit postcode falling in a
283	     * known region's range ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}) yields
284	     * that region. When the postcode is absent or in no known range, it falls back to the fixed
285	     * city-to-region table ({@code Sydney -> NSW}, {@code Melbourne -> VIC}, {@code Brisbane -> QLD}).
286	     * Returns {@code "UNKNOWN"} when neither source resolves a region.
287	     */
288	    @Transient
289	    public String getRegion() {
290	        String byPostcode = regionForPostcode(this.postcode);
291	        if (byPostcode != null) {
292	            return byPostcode;
293	        }
294	        if ("Sydney".equals(this.city)) {
295	            return "NSW";
296	        }
297	        if ("Melbourne".equals(this.city)) {
298	            return "VIC";
299	        }
300	        if ("Brisbane".equals(this.city)) {
301	            return "QLD";
302	        }
303	        return "UNKNOWN";
304	    }
