306	    /**
307	     * The owner's locality, derived on read from the region-and-hash {@link #getCustomerCode()
308	     * customer code}: the region segment before the first '-' of the customer code
309	     * ('<REGION>-<HASH8>'). Falls back to the owner's {@link #getRegion() region} when no customer
310	     * code has been assigned yet.
311	     */
312	    @Transient
313	    public String getLocality() {
314	        if (this.customerCode != null) {
315	            int dash = this.customerCode.indexOf('-');
316	            if (dash > 0) {
317	                return this.customerCode.substring(0, dash);
318	            }
319	        }
320	        return getRegion();
321	    }
