323	    /** The inclusive 4-digit postcode {@code {low, high}} range for {@code region}, or {@code null} when
324	     *  the region carries no range rule (i.e. {@code UNKNOWN} or any region absent from the table:
325	     *  {@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}). */
326	    public static int[] postcodeRangeForRegion(String region) {
327	        return REGION_POSTCODE_RANGES.get(region);
328	    }
329	
330	    /** The region whose postcode range contains {@code postcode}, or {@code null} when the postcode is
331	     *  absent, not a 4-digit value, or in no known range. */
332	    private static String regionForPostcode(String postcode) {
333	        if (postcode == null || !postcode.matches("^[0-9]{4}$")) {
334	            return null;
335	        }
336	        int value = Integer.parseInt(postcode);
337	        for (Map.Entry<String, int[]> entry : REGION_POSTCODE_RANGES.entrySet()) {
338	            int[] range = entry.getValue();
339	            if (value >= range[0] && value <= range[1]) {
340	                return entry.getKey();
341	            }
342	        }
343	        return null;
344	    }
345	
346	    /** Telephone country code -> the national-number length it requires ({@code +61} Australia => 9
347	     *  digits, {@code +1} NANP => 10), used to derive telephone values from the stored E.164 number.
348	     *  The country codes here carry no conflicting prefixes ({@code +61} does not start with
349	     *  {@code +1}), so a number matches at most one. */
350	    private static final Map<String, Integer> NATIONAL_NUMBER_LENGTHS = Map.of(
351	        "+61", 9, "+1", 10);
352	
353	    /**
354	     * The stored E.164 {@link #telephone} formatted for humans, derived on read: the country code, a
355	     * space, then the national digits grouped in threes (e.g. {@code "+61 412 345 678"}). Falls back
356	     * to the raw value when it is {@code null} or begins with no recognised country code.
357	     */
358	    @Transient
359	    public String getTelephoneDisplay() {
360	        if (this.telephone == null) {
361	            return null;
362	        }
363	        String countryCode = countryCodeOf(this.telephone);
364	        if (countryCode == null) {
365	            return this.telephone;
366	        }
367	        String national = this.telephone.substring(countryCode.length());
368	        StringBuilder grouped = new StringBuilder(countryCode);
369	        for (int i = 0; i < national.length(); i++) {
370	            if (i % 3 == 0) {
371	                grouped.append(' ');
372	            }
373	            grouped.append(national.charAt(i));
374	        }
375	        return grouped.toString();
376	    }
377	
378	    /** The recognised telephone country code that {@code telephone} begins with (e.g. {@code "+61"}),
379	     *  or {@code null} when it is {@code null} or begins with no recognised country code. */
380	    public static String countryCodeOf(String telephone) {
381	        if (telephone == null) {
382	            return null;
383	        }
384	        for (String countryCode : NATIONAL_NUMBER_LENGTHS.keySet()) {
385	            if (telephone.startsWith(countryCode)) {
386	                return countryCode;
387	            }
388	        }
389	        return null;
390	    }
391	
392	    /** The national-number length required for {@code countryCode}, or {@code null} when the country
393	     *  code carries no length rule (i.e. any code absent from the table: {@code +61 => 9},
394	     *  {@code +1 => 10}). */
395	    public static Integer nationalNumberLength(String countryCode) {
396	        return NATIONAL_NUMBER_LENGTHS.get(countryCode);
397	    }
398	
399	    /** The single Luhn check digit (0-9) over the decimal digits contained in {@code value}, scanning
400	     *  right to left and doubling every second digit; non-digit characters are ignored and a null or
401	     *  digit-free value yields {@code 0}. */
402	    private static int luhnCheckDigit(String value) {
403	        int sum = 0;
404	        boolean doubling = true;
405	        for (int i = (value == null ? 0 : value.length()) - 1; i >= 0; i--) {
406	            char c = value.charAt(i);
407	            if (c < '0' || c > '9') {
408	                continue;
409	            }
410	            int digit = c - '0';
411	            if (doubling) {
412	                digit *= 2;
413	                if (digit > 9) {
414	                    digit -= 9;
415	                }
416	            }
417	            sum += digit;
418	            doubling = !doubling;
419	        }
420	        return (10 - (sum % 10)) % 10;
421	    }
422	
423	    protected Set<Pet> getPetsInternal() {
424	        if (this.pets == null) {
425	            this.pets = new HashSet<>();
426	        }
427	        return this.pets;
428	    }
429	
430	    protected void setPetsInternal(Set<Pet> pets) {
431	        this.pets = pets;
432	    }
