434	    public List<Pet> getPets() {
435	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
436	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
437	        return Collections.unmodifiableList(sortedPets);
438	    }
439	
440	    public void setPets(List<Pet> pets) {
441	        this.pets = new HashSet<>(pets);
442	    }
443	
444	    public void addPet(Pet pet) {
445	        getPetsInternal().add(pet);
446	        pet.setOwner(this);
447	    }
448	
449	    /**
450	     * Return the Pet with the given name, or null if none found for this Owner.
451	     *
452	     * @param name to test
453	     * @return true if pet name is already in use
454	     */
455	    public Pet getPet(String name) {
456	        return getPet(name, false);
457	    }
458	
459	    /**
460	     * Return the Pet with the given name, or null if none found for this Owner.
461	     *
462	     * @param name to test
463	     * @return true if pet name is already in use
464	     */
465	    public Pet getPet(String name, boolean ignoreNew) {
466	        name = name.toLowerCase();
467	        for (Pet pet : getPetsInternal()) {
468	            if (!ignoreNew || !pet.isNew()) {
469	                String compName = pet.getName();
470	                compName = compName.toLowerCase();
471	                if (compName.equals(name)) {
472	                    return pet;
473	                }
474	            }
475	        }
476	        return null;
477	    }
478	
479	    public Pet getPet(Integer petId) {
480	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
481	    }
482	
483	    @Override
484	    public String toString() {
485	        return new ToStringCreator(this)
486	
487	            .append("id", this.getId())
488	            .append("new", this.isNew())
489	            .append("lastName", this.getLastName())
490	            .append("firstName", this.getFirstName())
491	            .append("address", this.address)
492	            .append("city", this.city)
493	            .append("telephone", this.telephone)
494	            .toString();
495	    }
496	}
